'use strict';
window.RegistrationUI={
 t:(z,e)=>I18n.language==='en'?e:z,
 escape(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));},
 async publicRequest(path,options={}){const r=await fetch('/api/v1/auth/'+path,{credentials:'same-origin',headers:{'Content-Type':'application/json',...options.headers},...options});const data=await r.json();if(!r.ok)throw Error(data.error||this.t('申请未提交，请重试','Request was not submitted. Please retry.'));return data;},
 open(){const t=this.t,h=this.escape;let box=document.getElementById('registration-modal');if(!box){box=document.createElement('dialog');box.id='registration-modal';box.className='registration-modal';document.body.append(box);}box.classList.add('reg-public');box.innerHTML='<div class="reg-heading"><div><span class="reg-kicker">'+t('申请系统访问权限','REQUEST SYSTEM ACCESS')+'</span><h2>'+t('账号注册申请','Request an Account')+'</h2><p>'+t('管理员批准并分配权限后，账号方可登录。','An administrator must approve your request and assign access before you can log in.')+'</p></div><button type="button" class="reg-close" aria-label="'+t('关闭','Close')+'">×</button></div><div class="reg-steps" aria-label="'+t('申请流程','Request Process')+'"><span><b>1</b>'+t('填写申请','Request')+'</span><i></i><span><b>2</b>'+t('管理员审批','Admin Review')+'</span><i></i><span><b>3</b>'+t('开通使用','Access Granted')+'</span></div><form class="reg-form"><div class="reg-section-heading reg-wide">'+t('基本资料','Your Details')+'</div><label>'+t('姓名','Name')+'<input name="display_name" required maxlength="80" autocomplete="name"></label><label>'+t('拟用账号','Requested Username')+'<input name="username" required pattern="[a-z][a-z0-9_]{2,39}" minlength="3" maxlength="40" autocomplete="username"><small>'+t('3–40位小写字母、数字或下划线，以字母开头。','3–40 lowercase letters, numbers or underscores, starting with a letter.')+'</small></label><label class="reg-wide">'+t('联系方式（电话或邮箱）','Contact (Phone or Email)')+'<input name="contact" required maxlength="160" autocomplete="email"></label><div class="reg-section-heading reg-wide">'+t('设置登录密码','Set Your Password')+'</div><label>'+t('密码','Password')+'<input type="password" name="password" required minlength="12" maxlength="128" autocomplete="new-password"><small>'+t('12–128个字符','12–128 characters')+'</small></label><label>'+t('确认密码','Confirm Password')+'<input type="password" name="confirm" required minlength="12" maxlength="128" autocomplete="new-password"></label><p class="error reg-wide" role="alert" id="reg-error"></p><div class="reg-actions reg-wide"><button type="button" class="button secondary" data-reg-cancel>'+t('取消','Cancel')+'</button><button class="button primary" type="submit">'+t('提交注册申请','Submit Request')+'</button></div></form>';
 box.querySelector('.reg-close').onclick=box.querySelector('[data-reg-cancel]').onclick=()=>box.close();box.onclose=()=>{box.querySelector('form')?.reset();};box.showModal();box.querySelector('input').focus();for(const input of box.querySelectorAll('input[type=password]')){const row=document.createElement('div');row.className='reg-password-row';input.before(row);row.append(input);const b=document.createElement('button');b.type='button';b.className='reg-password-toggle';b.textContent=t('显示','Show');b.setAttribute('aria-label',t('显示密码','Show Password'));b.onclick=()=>{const show=input.type==='password';input.type=show?'text':'password';b.textContent=show?t('隐藏','Hide'):t('显示','Show');b.setAttribute('aria-label',show?t('隐藏密码','Hide Password'):t('显示密码','Show Password'));b.setAttribute('aria-pressed',String(show));};row.append(b);}
 box.querySelector('form').onsubmit=async e=>{e.preventDefault();const form=e.target,d=Object.fromEntries(new FormData(form)),button=e.submitter,error=box.querySelector('#reg-error');error.textContent='';if(d.password!==d.confirm){error.textContent=t('两次密码不一致','Passwords do not match');return;}button.disabled=true;try{const {csrfToken}=await this.publicRequest('registration-token');delete d.confirm;const result=await this.publicRequest('registration-requests',{method:'POST',headers:{'Content-Type':'application/json','x-csrf-token':csrfToken},body:JSON.stringify(d)});form.reset();box.innerHTML='<div class="reg-success"><span aria-hidden="true">✓</span><h2>'+t('注册申请已提交','Account Request Submitted')+'</h2><p>'+t('请等待管理员审批。审批通过后，使用申请时填写的账号和密码登录。','Please wait for administrator approval, then log in with the username and password you submitted.')+'</p><button type="button" class="button primary">'+t('完成','Done')+'</button></div>';box.querySelector('button').onclick=()=>box.close();box.querySelector('button').focus();}catch(err){error.textContent=I18n.language==='en'?I18n.translate(err.message,true):err.message;button.disabled=false;}};
 },
 install(){if(this.installed)return;this.installed=true;const draw=Accounts.drawUsers.bind(Accounts);Accounts.drawUsers=(...args)=>{const r=draw(...args),tools=document.getElementById('account-filter');if(tools&&Business.can('users:manage')){const button=document.createElement('button');button.type='button';button.id='account-registration-requests';button.className='button secondary';button.dataset.noI18n='';button.textContent=this.t('注册申请审批','Account Requests');button.onclick=()=>this.list();const create=document.getElementById('account-create');if(create)create.after(button);else tools.append(button);API.request('/users/registration-requests').then(d=>{if(button.isConnected)button.textContent=this.t('注册申请审批','Account Requests')+(d.pending?' · '+d.pending:'');}).catch(()=>{});}return r;};},
 async list(status='PENDING'){const t=this.t,h=this.escape;try{const data=await API.request('/users/registration-requests?status='+status);dialog(t('注册申请审批','Account Requests'),'<div class="reg-admin"><label>'+t('申请状态','Request Status')+'<select id="reg-list-status">'+[['PENDING','待审批','Pending'],['APPROVED','已批准','Approved'],['REJECTED','已驳回','Rejected'],['ALL','全部','All']].map(([k,z,e])=>'<option value="'+k+'"'+(k===status?' selected':'')+'>'+t(z,e)+'</option>').join('')+'</select></label><div class="reg-request-list">'+(data.items.map(r=>'<article><div><strong data-no-i18n>'+h(r.display_name)+'</strong><p data-no-i18n>'+h(r.username)+' · '+h(r.contact)+'</p><small>'+h(BusinessTime.display(r.created_at))+' · '+t(...({PENDING:['待审批','Pending'],APPROVED:['已批准','Approved'],REJECTED:['已驳回','Rejected']}[r.status]))+'</small>'+(r.review_reason?'<p data-no-i18n>'+h(r.review_reason)+'</p>':'')+'</div>'+(r.status==='PENDING'?'<button type="button" class="button primary" data-reg-review="'+r.id+'">'+t('审批','Review')+'</button>':'')+'</article>').join('')||'<p>'+t('当前筛选暂无注册申请','No requests under this filter')+'</p>')+'</div></div>');document.getElementById('reg-list-status').onchange=e=>this.list(e.target.value);document.querySelectorAll('[data-reg-review]').forEach(b=>b.onclick=()=>this.review(data.items.find(r=>r.id===b.dataset.regReview)));}catch(e){notify(e.message);}},
 async review(r){const t=this.t,h=this.escape,o=await API.request('/users/options');dialog(t('审批注册申请','Review Account Request'),'<div class="reg-applicant"><strong data-no-i18n>'+h(r.display_name)+'</strong><span data-no-i18n>'+h(r.username)+' · '+h(r.contact)+'</span></div><form id="reg-review-form" class="reg-form"><label class="reg-wide">'+t('审批结果','Decision')+'<select name="decision"><option value="APPROVED">'+t('批准并启用账号','Approve and Activate')+'</option><option value="REJECTED">'+t('驳回申请','Reject Request')+'</option></select></label><label class="reg-wide" data-reg-grant>'+t('分配角色','Assign Role')+'<select name="role_code" required><option value="">'+t('请选择角色','Select a Role')+'</option>'+o.roles.map(x=>'<option value="'+h(x.code)+'">'+h(I18n.language==='en'?x.name_en||x.name:x.name)+'</option>').join('')+'</select></label><fieldset class="reg-wide" data-reg-grant><legend>'+t('授权数据范围','Data Access Scopes')+'</legend>'+o.projects.map(p=>'<div class="reg-scope"><label><input type="checkbox" name="project" value="'+p.id+'"><span data-no-i18n>'+h(p.name)+'</span></label><select data-reg-warehouse="'+p.id+'"><option value="">'+t('整个项目（须具备对应授权）','Entire Project (Requires Matching Access)')+'</option>'+o.warehouses.filter(w=>w.project_id===p.id).map(w=>'<option value="'+w.id+'">'+h(w.name)+'</option>').join('')+'</select></div>').join('')+'</fieldset><label class="reg-wide">'+t('审批说明（驳回必填）','Review Note (Required for Rejection)')+'<textarea name="reason" maxlength="1000" rows="3"></textarea></label><p id="reg-review-error" class="error reg-wide" role="alert"></p><div class="reg-actions reg-wide"><button type="button" class="button secondary" id="reg-review-back">'+t('返回申请列表','Back to Requests')+'</button><button class="button primary">'+t('确认审批','Confirm Review')+'</button></div></form>');const form=document.getElementById('reg-review-form');form.elements.decision.onchange=()=>{const approve=form.elements.decision.value==='APPROVED';form.querySelectorAll('[data-reg-grant]').forEach(n=>n.hidden=!approve);form.elements.role_code.required=approve;form.elements.reason.required=!approve;};document.getElementById('reg-review-back').onclick=()=>this.list();form.onsubmit=async e=>{e.preventDefault();const d=new FormData(form),decision=d.get('decision'),body={decision,reason:d.get('reason')};if(decision==='APPROVED')Object.assign(body,{role_code:d.get('role_code'),scopes:d.getAll('project').map(project_id=>({project_id,warehouse_id:form.querySelector('[data-reg-warehouse="'+project_id+'"]').value||null}))});e.submitter.disabled=true;try{await API.request('/users/registration-requests/'+r.id+'/review',{method:'POST',body});ProductContext.dirty=false;await Accounts.render();await this.list();}catch(err){document.getElementById('reg-review-error').textContent=I18n.language==='en'?I18n.translate(err.message,true):err.message;e.submitter.disabled=false;}};
 }
};
